{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"{
  "summary": "Allow post slugs up to 80 characters while keeping trailing hyphens out. Update the law in a separate PR first.",
  "stories": [
    {
      "id": "S1",
      "who": "Blog author",
      "want": "Long post titles to retain up to 80 characters in their slugs",
      "why": "Cutting at 40 characters removes meaningful words.",
      "from": null
    }
  ],
  "tasks": [
    {
      "title": "T1: Update the length law in a separate PR",
      "ends": "pr",
      "job": {
        "when": "A reviewer reads the slug length law",
        "result": "The documented and asserted maximum is 80 characters.",
        "check": {
          "how": "read",
          "what": "Read the law comment and its length assertion."
        },
        "serves": ["S1"],
        "fixture": "The existing law with generated titles up to 300 characters and seed 1."
      },
      "criteria": []
    },
    {
      "title": "T2: Extend slugs to 80 characters",
      "ends": "pr",
      "job": {
        "when": "A blog author generates a slug for a long post title",
        "result": "The slug retains the first 80 normalized characters, with a trailing hyphen removed.",
        "check": {
          "how": "test",
          "what": "Generate the fixture slug once and compare its full output."
        },
        "serves": ["S1"],
        "fixture": "One title: 'A practical guide to growing tomatoes on small balconies through the summer months'. Expected slug: 'a-practical-guide-to-growing-tomatoes-on-small-balconies-through-the-summer-mont'."
      },
      "criteria": []
    }
  ],
  "goal": {
    "job": {
      "when": "A blog author generates a slug after both changes land",
      "result": "A long title retains meaningful text through the 80-character limit, with no trailing hyphen.",
      "check": {
        "how": "test",
        "what": "In the final PR, verify the long-title output and the 80-character cutoff cases against the updated laws."
      },
      "serves": ["S1"],
      "fixture": "Generate each once: the 82-character title 'A practical guide to growing tomatoes on small balconies through the summer months', expecting 'a-practical-guide-to-growing-tomatoes-on-small-balconies-through-the-summer-mont'; and a title whose normalized slug has 79 letters followed by a hyphen and another word, expecting those 79 letters."
    },
    "criteria": [
      {
        "when": "The combined change receives its final review",
        "result": "The documented slug limit agrees with the 80-character behavior.",
        "check": {
          "how": "read",
          "what": "Read the updated law comment alongside the long-title acceptance examples."
        },
        "serves": ["S1"]
      }
    ]
  },
  "pointers": [
    {
      "at": "src/slug.laws.test.ts",
      "why": "T1 owns the law comment and maximum assertion change; its PR precedes T2."
    },
    {
      "at": "src/slug.ts",
      "why": "T2 owns the maximum change from 40 to 80 in the existing slugify helper."
    },
    {
      "at": "src/slug.test.ts",
      "why": "T2 owns regression coverage for longer slugs and the new cutoff boundary."
    },
    {
      "at": "AGENTS.md",
      "why": "Requires adjacent helper tests, identifies law files, and prohibits runtime dependencies."
    }
  ],
  "questions": [],
  "properties": [
    {
      "when": "A title normalizes to a slug longer than 40 characters",
      "result": "Its output equals the first 80 normalized characters with any final hyphen removed.",
      "why": "The current implementation stops at 40, losing meaningful title text. Cover normalized lengths 41, 79, 80, 81 and longer, including a hyphen at position 80; these longer-output expectations fail today.",
      "behavior": "new",
      "tool": "test",
      "code": [
        {
          "file": "src/slug.ts",
          "name": "slugify"
        }
      ]
    },
    {
      "when": "Any title is converted to a slug",
      "result": "The output contains at most 80 characters.",
      "why": "An unbounded slug would violate the requested limit. This relaxed ceiling already passes with the current 40-character cutoff.",
      "behavior": "existing",
      "tool": "test",
      "code": [
        {
          "file": "src/slug.ts",
          "name": "slugify"
        }
      ]
    },
    {
      "when": "Any title is converted to a slug",
      "result": "The output never ends with a hyphen.",
      "why": "Truncation can expose a separator at the end. The current implementation already removes it, and this guarantee must survive the longer limit.",
      "behavior": "existing",
      "tool": "test",
      "code": [
        {
          "file": "src/slug.ts",
          "name": "slugify"
        }
      ]
    }
  ],
  "interface": "```typescript\nexport function slugify(text: string): string;\n```",
  "exam": [
    {
      "path": "src/slug.laws.test.ts",
      "change": "In T1's separate PR, change 40 to 80 in the law comment and length assertion. Preserve the trailing-hyphen assertion.",
      "why": "The current law rejects the longer slugs explicitly requested by the ticket."
    }
  ],
  "gaps": [
    "The supplied folder has no Git metadata, so the stated commit could not be verified. The plan uses the supplied source as the baseline; planning was not blocked."
  ]
}"}}
